// Build CLI args for the aeromag detect command.
// Expects: { grid, meta, levels, wells?, pixel_size?, output? }
const body = items[0].json;
if (!body.grid || !body.meta || !body.levels) {
  throw new Error('aeromag specialist needs grid, meta, levels paths');
}
const args = ['run', 'aeromag',
  '--grid', body.grid,
  '--meta', body.meta,
  '--levels', body.levels];
if (body.pixel_size) { args.push('--pixel-size', String(body.pixel_size)); }
if (body.wells) { args.push('--wells', body.wells); }
if (body.output) { args.push('--output', body.output); }
return [{ json: { argv: args.join(' '), runner: $env.CESAROPS_RUNNER || '/home/cesarops/wreckhunter2000-1/n8n/pipeline_runner.sh' } }];

// Parse PipelineReport JSON; surface ranked candidates with classification.
const out = items[0].json.stdout || '{}';
let report;
try { report = JSON.parse(out); } catch (e) { return [{ json: { error: 'bad JSON from aeromag', raw: out.slice(0, 500) } }]; }
const cands = report.candidates || [];
return [{ json: {
  pipeline: 'aeromagnetic',
  gpu_available: report.gpu_available,
  n_candidates: cands.length,
  top: cands.slice(0, 10).map(c => ({
    lat: c.center_lat, lon: c.center_lon,
    score: c.combined_score,
    manmade: c.score_manmade,
    classification: c.classification,
    ground_truth: c.ground_truth,
    nearest_wreck: c.nearest_known_wreck,
    basin: c.basin
  })),
  report
} }];
